// Input: items[0].json.newsletter
const p = items[0].json.newsletter;

const issue = {
  id: p.issue.id,
  brand: p.issue.brand,
  locale: p.issue.locale
};

// rows for newsletter_segments
const segments = p.segments.map(s => ({
  issue_id: p.issue.id,
  ord: s.order,
  type: s.type,
  title: s.data?.title ?? null,
  dek: s.data?.dek ?? null,
  img_url: s.data?.img ?? null,
  href: s.data?.href ?? null,
  data: s.data // keep the full JSON for flexibility
}));

return [
  { json: { issue, segments } }
];

// n8n Function — combine 4 scraped inputs into one normalized newsletter payload

const base = 'https://www.oakcent.com';
function abs(u) {
  if (!u) return u;
  return /^https?:\/\//i.test(u) ? u : base + u;
}

// Index inputs by kind
const by = {};
for (const it of items.map(i => i.json)) {
  if (it.pageUrl && it.pageUrl.includes('/magazine/')) by.article = it;
  else if (it.facts_location || it.collection_name) by.project = it;
  else if ((it.title && it.title.trim() === 'Sand') || it.grid_images) by.collection = it;
  else if ((it.title && it.title.trim() === 'Heritage') || it.tiles_images) by.pattern = it;
}

const segments = [];

// HERO from article
if (by.article) {
  segments.push({
    order: segments.length + 1,
    type: 'hero',
    data: {
      title: by.article.title || '',
      dek: (by.article.firstParagraph || '').trim(),
      img: abs(by.article.heroImg),
      href: by.article.pageUrl
    }
  });
}

// GRID from Sand collection
if (by.collection && Array.isArray(by.collection.grid_images) && by.collection.grid_images.length) {
  const itemsGrid = by.collection.grid_images.map((img, i) => ({
    title: (by.collection.grid_titles && by.collection.grid_titles[i]) ? by.collection.grid_titles[i] : '',
    img: abs(img),
    href: 'https://www.oakcent.com/floor-collection/sand'
  }));
  segments.push({
    order: segments.length + 1,
    type: 'grid',
    data: { heading: 'Sand collection — highlights', items: itemsGrid }
  });
}

// PROJECT intro + gallery
if (by.project) {
  segments.push({
    order: segments.length + 1,
    type: 'project_intro',
    data: {
      title: by.project.title || '',
      chip: by.project.collection_name || '',
      attrs: {
        location: by.project.facts_location || '',
        architect: by.project.facts_architect || '',
        photo: by.project.facts_photoCredits || ''
      },
      img: abs(by.project.heroImg)
    }
  });

  const gallery = [];
  if (by.project.firstBlock_img) gallery.push(abs(by.project.firstBlock_img));
  if (by.project.secondBlock_img) gallery.push(abs(by.project.secondBlock_img));

  segments.push({
    order: segments.length + 1,
    type: 'project_gallery',
    data: {
      summary: (by.project.secondBlock_lead || '').trim(),
      images: gallery
    }
  });
}

// PATTERN tiles (Heritage)
if (by.pattern && Array.isArray(by.pattern.tiles_images) && by.pattern.tiles_images.length) {
  const patternTiles = by.pattern.tiles_images.map((img, i) => ({
    title: (by.pattern.tiles_titles && by.pattern.tiles_titles[i]) ? by.pattern.tiles_titles[i] : '',
    img: abs(img),
    href: 'https://www.oakcent.com/collection-heritage'
  }));
  segments.push({
    order: segments.length + 1,
    type: 'grid',
    data: { heading: 'Pattern collection — Heritage', items: patternTiles }
  });
}

// COLLECTION gallery from Sand
if (by.collection && Array.isArray(by.collection.galery_images) && by.collection.galery_images.length) {
  segments.push({
    order: segments.length + 1,
    type: 'collection_gallery',
    data: {
      title: 'Sand — in real spaces',
      summary: (by.collection.summary || '').trim(),
      images: by.collection.galery_images.map(abs)
    }
  });
}

// CTA — prefer project CTA text; link to project contact anchor
if (by.project && by.project.cta_text) {
  segments.push({
    order: segments.length + 1,
    type: 'cta',
    data: {
      text: by.project.cta_text.replace(/\s+/g, ' ').trim(),
      href: 'https://www.oakcent.com/projects/bernard-visitor-center#footer-contact-form'
    }
  });
}

// Build assets.images without flatMap
const allImgs = [];
segments.forEach(seg => {
  const d = seg.data || {};
  if (Array.isArray(d.images)) d.images.forEach(u => { if (u) allImgs.push(u); });
  if (d.img) allImgs.push(d.img);
  if (Array.isArray(d.items)) d.items.forEach(it => { if (it && it.img) allImgs.push(it.img); });
});
const images = Array.from(new Set(allImgs.filter(Boolean)));

const payload = {
  issue: { id: 'oakcent-weekly-001', brand: 'OAKCENT', locale: 'en' },
  sources: {
    article: by.article ? { url: by.article.pageUrl, title: by.article.title } : null,
    project: by.project ? { url: 'https://www.oakcent.com/projects/bernard-visitor-center', title: by.project.title } : null,
    collection: by.collection ? { url: 'https://www.oakcent.com/floor-collection/sand', title: 'Sand' } : null,
    pattern: by.pattern ? { url: 'https://www.oakcent.com/collection-heritage', title: 'Heritage' } : null
  },
  segments,
  assets: { images }
};

return [{ json: { newsletter: payload } }];

// n8n Function node: adapt your `newsletter` -> renderer input
// Input: items[0].json = { newsletter: {...} }  (or the newsletter object itself)
// Output: items[0].json = { meta, segments }  (renderer-ready)

const item = items[0];
const root = item.json || {};
const nl = root.newsletter || root; // supports both shapes

const BASE = 'https://www.oakcent.com';
const abs = (u) => u ? (String(u).startsWith('http') ? u : BASE + u) : null;
const para = (t) => {
  if (!t) return '';
  return '<p>' + String(t).split(/\n+/).map(s => s.trim()).filter(Boolean).join('</p><p>') + '</p>';
};

// Helpers to find segments by type
const segs = Array.isArray(nl.segments) ? nl.segments : [];
const segByType = (t) => {
  for (let i = 0; i < segs.length; i++) if ((segs[i] || {}).type === t) return segs[i];
  return null;
};
const firstGrid = (() => {
  for (let i = 0; i < segs.length; i++) {
    const s = segs[i];
    if (s.type === 'grid' && /Sand/i.test(s.data?.heading || '')) return s;
  }
  for (let i = 0; i < segs.length; i++) if (segs[i].type === 'grid') return segs[i];
  return null;
})();
const patternGrid = (() => {
  for (let i = 0; i < segs.length; i++) {
    const s = segs[i];
    if (s.type === 'grid' && /Pattern/i.test(s.data?.heading || '')) return s;
  }
  return null;
})();

// Pull source bits
const hero      = (segByType('hero') || {}).data || {};
const projIntro = (segByType('project_intro') || {}).data || {};
const projGal   = (segByType('project_gallery') || {}).data || {};
const collGal   = (segByType('collection_gallery') || {}).data || {};
const cta       = (segByType('cta') || {}).data || {};

const brand = (nl.issue && nl.issue.brand) || 'Oakcent';
const coll  = (nl.sources && nl.sources.collection) || {};
const proj  = (nl.sources && nl.sources.project) || {};
const art   = (nl.sources && nl.sources.article) || {};
const patt  = (nl.sources && nl.sources.pattern) || {};

// Meta
const subject = `${brand} — ${coll.title || 'Collection'} × ${proj.title || 'Project'}`;
const preheader = (hero.dek || projGal.summary || '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 140);

// Right images from the first grid
function gridToRightImages(g) {
  const arr = (g && g.data && Array.isArray(g.data.items)) ? g.data.items : [];
  const out = [];
  for (let i = 0; i < arr.length && out.length < 2; i++) {
    const it = arr[i];
    if (it && (it.img || it.href)) {
      out.push({ url: abs(it.img), alt: it.title || '' });
    }
  }
  return out;
}
const rightImages = gridToRightImages(firstGrid);

// Pattern pick (prefer Herringbone)
const patternPick = (() => {
  const arr = (patternGrid && patternGrid.data && Array.isArray(patternGrid.data.items)) ? patternGrid.data.items : [];
  for (let i = 0; i < arr.length; i++) {
    if (/herringbone/i.test(arr[i].title || '')) return arr[i];
  }
  return arr[0] || {};
})();

// Build renderer-ready payload
const payload = {
  meta: { subject, preheader },
  segments: [
    {
      type: 'segment_intro',
      data: {
        logo_url: abs('/logo-oakcent.svg'),
        hero_image_url: abs(hero.img),
        kicker: 'Magazine',
        title: hero.title || art.title,
        body_html: para(hero.dek),
        cta_text: 'Read the article',
        cta_url: art.url || hero.href,
        right_images: rightImages
      }
    },
    {
      type: 'segment_project_story',
      data: {
        top_image_url: abs(projIntro.img || (Array.isArray(projGal.images) ? projGal.images[0] : null)),
        title: projIntro.title || proj.title,
        body_html: para([
          projGal.summary,
          (projIntro.attrs && (projIntro.attrs.architect || projIntro.attrs.location || projIntro.attrs.photo))
            ? `${projIntro.attrs.architect || ''}${(projIntro.attrs.architect && projIntro.attrs.location) ? ' — ' : ''}${projIntro.attrs.location || ''}${projIntro.attrs.photo ? ` · Photo: ${projIntro.attrs.photo}` : ''}`
            : ''
        ].filter(Boolean).join('\n')),
        cta_text: 'See the project',
        cta_url: proj.url,
        left_images: (() => {
          const imgs = Array.isArray(projGal.images) ? projGal.images.slice(0, 2) : [];
          const out = [];
          for (let i = 0; i < imgs.length; i++) {
            out.push({ url: abs(imgs[i]), alt: projIntro.title || proj.title || 'Project' });
          }
          return out;
        })()
      }
    },
    {
      type: 'segment_collection_and_pattern',
      data: {
        collection: {
          label: 'Collection:',
          name: coll.title || '—',
          desc_html: para(collGal.summary || ''),
          swatch_url: abs(
            (firstGrid && firstGrid.data && firstGrid.data.items && firstGrid.data.items[0])
              ? firstGrid.data.items[0].img
              : null
          ),
          cta_text: 'Explore the collection',
          cta_url: coll.url
        },
        pattern: {
          label: 'Pattern:',
          name: patt.title || ((patternPick.title || '').split(':')[0] || '—'),
          desc_html: para(patternPick.title || ''),
          swatch_url: abs(patternPick.img),
          cta_text: 'Explore patterns',
          cta_url: patt.url
        }
      }
    },
    {
      type: 'segment_full_width_image',
      data: {
        image_url: abs((Array.isArray(collGal.images) && collGal.images[0]) ? collGal.images[0] : hero.img),
        alt: coll.title ? `${coll.title} — gallery` : 'Gallery'
      }
    },
    {
      type: 'segment_dark_cta',
      data: {
        title: cta.text || 'Let’s talk',
        cta_text: 'OPEN',
        cta_url: cta.href || coll.url || proj.url
      }
    }
  ]
};

// Clean empty image arrays (defensive)
payload.segments.forEach(s => {
  if (s?.data?.right_images) s.data.right_images = s.data.right_images.filter(i => i && i.url);
  if (s?.data?.left_images)  s.data.left_images  = s.data.left_images.filter(i => i && i.url);
});

return [{ json: payload }];

// n8n Function node: Build Oakcent-style newsletter (ALL CONTENT CENTERED)
// Input: items[0].json = { meta, segments: [{ type, data }, ...] }
// Output: item.json.html (string) + item.binary.newsletter (HTML file)

// ---------- helpers ----------
const item = items[0];
const data = item.json || {};

const esc = (v = '') => String(v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const aIf = (cond, html) => cond ? html : '';
const space = (h=12) => `<div style="line-height:0; height:${h}px; font-size:0;">&nbsp;</div>`;
const dividerH = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" align="center"><tr><td style="border-top:1px solid #cdc5bf; height:1px; line-height:1px; font-size:0;"></td></tr></table>`;
const btnOutline = (href, text) =>
  `<a href="${esc(href)}" style="display:inline-block; padding:12px 18px; border:1px solid #3b3b3b; color:#3b3b3b; text-decoration:none; border-radius:4px; font-family:Arial, sans-serif;">${esc(text)}</a>`;
const btnSolidWhite = (href, text) =>
  `<a href="${esc(href)}" style="display:inline-block; padding:12px 18px; background:#ffffff; color:#111827; text-decoration:none; border-radius:2px; font-family:Arial, sans-serif; font-weight:bold;">${esc(text)}</a>`;

// brand palette (inline for email)
const BG = '#e9dfd7';        // light beige page background
const TEXT = '#3b3b3b';      // primary text
const MUTED = '#6b6b6b';     // secondary text
const DARK = '#232323';      // dark block background

// ---------- layout ----------
const layoutStart = (meta = {}) => `<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="x-apple-disable-message-reformatting">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${esc(meta.subject || '')}</title>
</head>
<body style="margin:0; padding:0; background:${BG};">
  <div style="display:none; visibility:hidden; opacity:0; color:transparent; height:0; width:0; overflow:hidden;">
    ${esc(meta.preheader || '')}
  </div>
  <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background:${BG};">
    <tr>
      <td align="center">
        <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="600" style="width:600px; max-width:100%;">
          <tr><td align="center" style="padding:20px; font-family:Arial, sans-serif; color:${TEXT}; font-size:16px; line-height:1.5; text-align:center;">`;

const layoutEnd = `</td></tr></table></td></tr></table></body></html>`;

// ---------- segments ----------

// 1) HERO / INTRO (centered logo, hero, two columns centered)
function segment_intro(d = {}) {
  const right = (d.right_images || []).slice(0,2);
  return `
  ${aIf(d.logo_url, `
    <div style="text-align:center;">${aIf(d.logo_url, `<img src="${esc(d.logo_url)}" alt="${esc(d.logo_alt || 'Logo')}" width="120" style="display:inline-block; border:0; margin:0 auto;">`)}</div>
    ${space(12)}`)}
  ${aIf(d.hero_image_url, `
    <img src="${esc(d.hero_image_url)}" alt="${esc(d.hero_image_alt || '')}" width="560" style="display:block; width:100%; max-width:560px; border:0; margin:0 auto;">
    ${space(16)}`)}

  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" align="center">
    <tr>
      <td valign="top" width="66%" align="center" style="padding-right:16px; text-align:center;">
        ${aIf(d.kicker, `<div style="text-transform:uppercase; letter-spacing:.04em; font-size:12px; color:${MUTED};">${esc(d.kicker)}</div>`)}
        ${aIf(d.title, `<h1 style="margin:6px 0 10px; color:${TEXT}; font-size:24px;">${esc(d.title)}</h1>`)}
        ${aIf(d.body_html, `<div style="text-align:center;">${d.body_html}</div>`)}
        ${space(12)}
        ${aIf(d.cta_url, btnOutline(d.cta_url, d.cta_text || 'Zjistit více'))}
      </td>
      <td valign="top" width="34%" align="center" style="text-align:center;">
        ${right.map((u,i) => `
          ${i ? space(12) : ''}<img src="${esc(u.url)}" alt="${esc(u.alt || '')}" width="180" style="display:block; width:100%; max-width:180px; border:0; margin:0 auto;">
        `).join('')}
      </td>
    </tr>
  </table>`;
}

// 2) PROJECT STORY (centered)
function segment_project_story(d = {}) {
  const left = (d.left_images || []).slice(0,2);
  return `
  ${aIf(d.top_image_url, `
    <img src="${esc(d.top_image_url)}" alt="${esc(d.top_image_alt || '')}" width="560" style="display:block; width:100%; max-width:560px; border:0; margin:0 auto;">
    ${space(16)}`)}

  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" align="center">
    <tr>
      <td valign="top" width="40%" align="center" style="padding-right:16px; text-align:center;">
        ${left.map((u,i) => `
          ${i ? space(12) : ''}<img src="${esc(u.url)}" alt="${esc(u.alt || '')}" width="220" style="display:block; width:100%; max-width:220px; border:0; margin:0 auto;">
        `).join('')}
      </td>
      <td valign="top" width="60%" align="center" style="text-align:center;">
        ${aIf(d.title, `<h2 style="margin:0 0 8px; color:${TEXT}; font-size:22px;">${esc(d.title)}</h2>`)}
        ${aIf(d.body_html, `<div style="text-align:center;">${d.body_html}</div>`)}
        ${space(12)}
        ${aIf(d.cta_url, btnOutline(d.cta_url, d.cta_text || 'Prohlédněte si projekt'))}
      </td>
    </tr>
  </table>`;
}

// 3 & 4) COLLECTION / PATTERN rows (centered text; keeps left divider)
function swatchRow(r = {}) {
  return `
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" align="center">
    <tr>
      <td valign="top" width="120" align="center" style="padding-right:16px; text-align:center;">
        ${aIf(r.swatch_url, `<img src="${esc(r.swatch_url)}" alt="${esc(r.swatch_alt || '')}" width="100" style="display:block; width:100px; height:100px; border-radius:50%; border:0; margin:0 auto;">`)}
      </td>
      <td valign="top" align="center" style="border-left:1px solid #cdc5bf; padding-left:16px; text-align:center;">
        ${aIf(r.label, `<div style="font-size:12px; color:${MUTED}; text-transform:uppercase; letter-spacing:.02em;">${esc(r.label)}</div>`)}
        ${aIf(r.name, `<div style="font-size:20px; margin:6px 0 6px; color:${TEXT};"><strong>${esc(r.name)}</strong></div>`)}
        ${aIf(r.desc_html, `<div style="text-align:center;">${r.desc_html}</div>`)}
        ${space(10)}
        ${aIf(r.cta_url, btnOutline(r.cta_url, r.cta_text || 'Zjistit více'))}
      </td>
    </tr>
  </table>`;
}
function segment_collection_and_pattern(d = {}) {
  const top = swatchRow(d.collection || {});
  const bottom = swatchRow(d.pattern || {});
  return `${top}${space(12)}${dividerH}${space(12)}${bottom}`;
}

// 5) FULL-WIDTH IMAGE (centered)
function segment_full_width_image(d = {}) {
  return `
  <img src="${esc(d.image_url)}" alt="${esc(d.alt || '')}" width="560" style="display:block; width:100%; max-width:560px; border:0; margin:0 auto;">`;
}

// 6) DARK CTA (already centered)
function segment_dark_cta(d = {}) {
  const socials = (d.socials || []).slice(0,8);
  return `
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${DARK}; border-radius:2px;" align="center">
    <tr><td align="center" style="padding:28px 16px; text-align:center;">
      ${aIf(d.title, `<div style="font-family:Arial, sans-serif; color:#ffffff; font-size:22px; font-weight:bold; margin:0 0 10px;">${esc(d.title)}</div>`)}
      ${aIf(d.subtitle, `<div style="font-family:Arial, sans-serif; color:#e5e5e5; margin:0 0 14px;">${esc(d.subtitle)}</div>`)}
      ${aIf(d.cta_url, btnSolidWhite(d.cta_url, d.cta_text || 'OPEN'))}
      ${aIf(socials.length, `
        ${space(16)}
        <table role="presentation" cellpadding="0" cellspacing="0" border="0" align="center">
          <tr>
            ${socials.map(s => `
              <td style="padding:0 6px;">
                <a href="${esc(s.url)}"><img src="${esc(s.icon_url)}" alt="${esc(s.alt || '')}" width="20" style="display:block; border:0; margin:0 auto;"></a>
              </td>
            `).join('')}
          </tr>
        </table>`)}
    </td></tr>
  </table>`;
}

// map of segment types
const renderers = {
  segment_intro,
  segment_project_story,
  segment_collection_and_pattern,
  segment_full_width_image,
  segment_dark_cta,
};

// ---------- build body ----------
let body = '';
const list = Array.isArray(data.segments) ? data.segments : [];
for (let i = 0; i < list.length; i++) {
  const seg = list[i] || {};
  const fn = renderers[seg.type];
  if (fn) {
    body += fn(seg.data || {});
  } else {
    body += `<!-- Missing renderer for ${esc(seg.type)} -->`;
  }
  if (i < list.length - 1) body += space(18);
}

// ---------- finalize ----------
const html = layoutStart(data.meta || {}) + body + layoutEnd;

item.json.html = html;
item.binary = item.binary || {};
item.binary.newsletter = {
  data: Buffer.from(html, 'utf8').toString('base64'),
  fileName: 'newsletter.html',
  mimeType: 'text/html',
};

return items;

// n8n Function node: Build Oakcent-style newsletter
// Input: items[0].json = { meta, segments: [{ type, data }, ...] }
// Output: item.json.html (string) + item.binary.newsletter (HTML file)

// ---------- helpers ----------
const item = items[0];
const data = item.json || {};

const esc = (v = '') => String(v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const aIf = (cond, html) => cond ? html : '';
const space = (h=12) => `<div style="line-height:0; height:${h}px; font-size:0;">&nbsp;</div>`;
const dividerH = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" align="center"><tr><td style="border-top:1px solid #cdc5bf; height:1px; line-height:1px; font-size:0;"></td></tr></table>`;
const btnOutline = (href, text) =>
  `<a href="${esc(href)}" style="display:inline-block; padding:12px 18px; border:1px solid #3b3b3b; color:#3b3b3b; text-decoration:none; border-radius:4px; font-family:'RomNarrow','Roboto Condensed',Helvetica,Arial,sans-serif;
">${esc(text)}</a>`;
const btnSolidWhite = (href, text) =>
  `<a href="${esc(href)}" style="display:inline-block; padding:12px 18px; background:#ffffff; color:#111827; text-decoration:none; border-radius:2px; font-family:'RomNarrow','Roboto Condensed',Helvetica,Arial,sans-serif;
 font-weight:bold;">${esc(text)}</a>`;

