// ---------- reusable background section with VML fallback ----------
function bgSection(contentHtml, imageUrl, options = {}) {
  if (!imageUrl) {
    return `
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
        <tr><td style="padding:${options.padding || '0'};">${contentHtml}</td></tr>
      </table>`;
  }

  const position = options.position || 'center center';
  const size = options.size || 'cover';
  const repeat = options.repeat || 'no-repeat';
  const padding = options.padding || '0';

  const overlayRGBA = options.overlayRGBA || null;
  const overlayHex = options.overlayHex || CONFIG.BG_DARK_OVERLAY;
  const overlayOpacity = typeof options.overlayOpacity === 'number' ? options.overlayOpacity : 0;

  const cssBg = overlayRGBA
    ? `background: linear-gradient(${overlayRGBA}, ${overlayRGBA}), url('${esc(imageUrl)}'); background-position:${position}; background-repeat:${repeat}; background-size:${size};`
    : `background-image:url('${esc(imageUrl)}'); background-position:${position}; background-repeat:${repeat}; background-size:${size};`;

  const vml = `
  <!--[if gte mso 9]>
  <v:rect xmlns:v="urn:schemas-microsoft-com:vml" fill="true" stroke="false"
          style="mso-fit-shape-to-text:true; width:600px;">
    <v:fill type="frame" src="${esc(imageUrl)}" color="${esc(overlayHex)}" ${(overlayOpacity>0)?`opacity="${String(overlayOpacity)}"`:''} />
    <v:textbox inset="0,0,0,0">
  <![endif]-->`;

  const vmlEnd = `
  <!--[if gte mso 9]>
    </v:textbox>
  </v:rect>
  <![endif]-->`;

  return `
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="${cssBg}">
    <tr>
      <td style="padding:${padding};">
        ${vml}
          ${contentHtml}
        ${vmlEnd}
      </td>
    </tr>
  </table>`;
}

