import axios from 'axios';
import { XMLParser } from 'fast-xml-parser';

const odooUrl = $json.odoo_url;  // e.g. "https://yourdomain.odoo.com/xmlrpc/2"
const db = $json.db_name;
const username = $json.user_name;
const password = $json.user_password;

const parser = new XMLParser();

// helper to send XML-RPC calls
async function odooCall(endpoint, xml) {
  const res = await axios.post(`${odooUrl}/${endpoint}`, xml, {
    headers: { 'Content-Type': 'text/xml' }
  });
  return parser.parse(res.data);
}

